@sig trait ConditionAssessmentOwner_Api {
  def id: Art.BridgeId
  def conditionEvidence_Id : Art.PortId
  def conditionAssessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var conditionAssessment: Vehicle_Mode_Coordinator.ConditionAssessment.Type = $

  def put_conditionAssessment(value : Vehicle_Mode_Coordinator.ConditionAssessment.Type) : Unit = {
    Contract(
      Modifies(conditionAssessment),
      Ensures(
        conditionAssessment == value
      )
    )
    Spec {
      conditionAssessment = value
    }

    Art.putValue(conditionAssessment_Id, Vehicle_Mode_Coordinator.ConditionAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ConditionAssessmentOwner_Initialization_Api (
  val id: Art.BridgeId,
  val conditionEvidence_Id : Art.PortId,
  val conditionAssessment_Id : Art.PortId) extends ConditionAssessmentOwner_Api

@datatype class ConditionAssessmentOwner_Operational_Api (
  val id: Art.BridgeId,
  val conditionEvidence_Id : Art.PortId,
  val conditionAssessment_Id : Art.PortId) extends ConditionAssessmentOwner_Api {

  // Logika spec var representing port state for incoming data port
  @spec var conditionEvidence: Vehicle_Mode_Coordinator.ConditionEvidence = $

  def get_conditionEvidence() : Option[Vehicle_Mode_Coordinator.ConditionEvidence] = {
    Contract(
      Ensures(
        Res == Some(conditionEvidence)
      )
    )
    val value : Option[Vehicle_Mode_Coordinator.ConditionEvidence] = Art.getValue(conditionEvidence_Id) match {
      case Some(Vehicle_Mode_Coordinator.ConditionEvidence_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port conditionEvidence.  Expecting 'Vehicle_Mode_Coordinator.ConditionEvidence_Payload' but received ${v}")
        None[Vehicle_Mode_Coordinator.ConditionEvidence]()
      case _ => None[Vehicle_Mode_Coordinator.ConditionEvidence]()
    }
    return value
  }
}
